import os
from google.oauth2.credentials import Credentials
from googleapiclient.discovery import build

TOKEN=os.path.join(os.environ.get('HERMES_HOME',''), 'google_token.json')
creds=Credentials.from_authorized_user_file(TOKEN)
drive=build('drive','v3',credentials=creds)
docs=build('docs','v1',credentials=creds)
sheets=build('sheets','v4',credentials=creds)
FM='application/vnd.google-apps.folder'

def mkfolder(name,parent=None):
    body={'name':name,'mimeType':FM}
    if parent: body['parents']=[parent]
    x=drive.files().create(body=body,fields='id,name,webViewLink').execute()
    x['url']=f"https://drive.google.com/drive/folders/{x['id']}"
    return x

def mkdoc(title,text,parent):
    x=docs.documents().create(body={'title':title}).execute(); did=x['documentId']
    docs.documents().batchUpdate(documentId=did,body={'requests':[{'insertText':{'location':{'index':1},'text':text}}]}).execute()
    drive.files().update(fileId=did,addParents=parent,fields='id,parents').execute()
    return {'id':did,'name':title,'url':f'https://docs.google.com/document/d/{did}/edit'}

